# -*- coding: utf-8 -*-
"""Lecture 38 vignette pool A -- Mycobacterial infections: mycobacterial biology, infection versus disease,
transmission and progression risk, presentation and differential (pulmonary and extrapulmonary), the
tuberculin skin test (risk-group cut-offs worked from the vignette), the interferon-gamma release assay, and
sputum and imaging (slides 4-29).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md (2026-10-29): the key names the decisive clue and
the fact; each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:". Cut-off
items show the reasoning: risk group -> cut-off -> compare the induration.

Cut-off groups are the slide's own (s22): 5 mm = human immunodeficiency virus, recent close contact,
transplant, major immunosuppression, imaging suggesting prior tuberculosis; 10 mm = increased exposure risk
(residence in a high-incidence area, s14), high-risk congregate settings, children under 5; 15 mm = no known
risk factors. "Selected medical risks" is never used to place a patient (the slide does not name them).
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e6l38_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


